const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},save=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('浏览器无法保存，本次仍可正常使用。');return}if(k.startsWith('tcf-checks-'))trainingSaved()};
let theme=read('tcf-theme','light'),day='push',remaining=90,deadline=0,interval=null,sources=[];
function applyTheme(){document.querySelector('meta[name="theme-color"]').setAttribute('content',theme==='dark'?'#151410':'#faf8f3');document.documentElement.classList.toggle('dark',theme==='dark');$('#theme').textContent=theme==='dark'?'☀':'☾';$('#theme').setAttribute('aria-label',theme==='dark'?'切换浅色模式':'切换夜间模式')};applyTheme();$('#theme').onclick=()=>{theme=theme==='dark'?'light':'dark';save('tcf-theme',theme);applyTheme()};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2500)}
function mediaExample(e){const m=exerciseMedia[e.id];if(!m)return '';return `<figure class="motion-example"><div class="motion-stage"><video controls playsinline muted loop preload="none" width="180" height="180" data-clip="media/opengym/${m.id}.mp4" data-poster="media/opengym/${m.id}.webp" aria-label="${esc(m.title)}动作示范"></video><p class="motion-error" hidden>动画暂时无法播放，请稍后重试或查看下方文字说明。</p></div><figcaption><div class="eyebrow">MOVEMENT STUDY</div><span class="label">${m.type}</span><h3>${m.title}</h3><p>${m.note}</p><div class="motion-controls"><button type="button" data-motion-play>播放示范</button><label>播放速度 <select data-motion-speed aria-label="${esc(m.title)}播放速度"><option value="0.5">0.5× 慢速</option><option value="0.75">0.75×</option><option value="1" selected>1× 正常</option></select></label></div><small>openGym · <a href="https://github.com/DuarteSantos8/openGym/blob/5fdb229fe40d2299ba0c82b84c86259d73944aba/catalogue/exercises/${m.id}.json" target="_blank" rel="noopener noreferrer">${esc(m.name)} ↗</a><br>© Aliaksandr Makatserchyk / <a href="https://gymvisual.com/" target="_blank" rel="noopener noreferrer">Gym visual</a><br>180 px 原始素材 · <a href="#sources">素材说明</a></small></figcaption></figure>`}
function bindMedia(){document.querySelectorAll('.motion-example').forEach(figure=>{const video=figure.querySelector('video'),button=figure.querySelector('[data-motion-play]'),error=figure.querySelector('.motion-error');const loadMedia=()=>{if(!video.getAttribute('src')){video.poster=video.dataset.poster;video.src=video.dataset.clip;video.load()}};const parent=figure.closest('details');if(parent){parent.addEventListener('toggle',()=>{if(parent.open)loadMedia();else video.pause()});if(parent.open)loadMedia()}else loadMedia();button.onclick=async()=>{loadMedia();if(!video.paused){video.pause();return}try{await video.play()}catch{error.hidden=false;error.textContent='播放未能开始，请使用画面下方的播放按钮重试。'}};video.addEventListener('play',()=>{document.querySelectorAll('.motion-example video').forEach(other=>{if(other!==video)other.pause()});button.textContent='暂停示范';error.hidden=true});video.addEventListener('pause',()=>button.textContent='播放示范');video.addEventListener('error',()=>{error.hidden=false;button.textContent='重试播放';video.removeAttribute('src')});figure.querySelector('[data-motion-speed]').onchange=event=>{video.playbackRate=Number(event.target.value)}})}
function detail(e){return `<div class="detail-body">${mediaExample(e)}<div class="exercise-lesson-row">${originalExerciseLink(e.id)}</div><span class="label">${e.muscles}</span><p><b>准备</b>　${e.setup}</p><p><b>动作</b>　${e.motion}</p><p><b>常见错误</b>　${e.error}</p><div class="note"><b>动作调整</b>　${e.beginner}</div></div>`}
function exerciseDetails(e){return `<details id="${e.id}"><summary>${e.name}</summary>${detail(e)}</details>`}
function warmupHtml(d){return warmups[d].map(([t,p])=>`<h3>${t}</h3><p>${p}</p>`).join('')}
function header(title,sub,eyebrow='TRAINING LIBRARY'){return `<div class="wrap page-top"><div class="breadcrumb"><a href="#home">首页</a>　/　${title}</div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>`}
function home(){return `<div class="wrap"><section class="hero"><div><div class="eyebrow">A FIELD GUIDE TO BETTER TRAINING</div><h1 class="hero-quote">好好吃饭，<br>好好睡觉，<br><em>好好训练，<br>好好生活。</em></h1><div class="quote-credit">#谭成义</div><p>从推拉腿，到每一次发力。<br>一本可以带进健身房的训练手册，<br>陪你循序渐进，也陪你回到基础。</p><div class="actions"><a class="primary" href="#library">翻开训练手册 →</a><a class="text-link" href="#workout">开始今日训练 ↗</a></div></div><div class="hero-art" aria-label="训练手册书封插画"><div class="back-book"></div><div class="hero-book"><div class="book-en">THE TRAINING MANUAL</div><h2>谭师<br>训练手册</h2><div class="barbell"><b></b><b></b><i></i><b></b><b></b></div><p>动作 · 节奏 · 长期</p></div><span class="art-caption">读懂动作，再开始训练。</span></div></section><div class="principles"><div><small>01</small><strong>动作质量</strong><p>先让每一次可控，再让重量增长。</p></div><div><small>02</small><strong>循序渐进</strong><p>选择适合自己的版本，记录点滴进步。</p></div><div><small>03</small><strong>长期练习</strong><p>把训练与恢复，放回日常生活。</p></div></div><section id="library"><div class="section-head"><div><div class="eyebrow">THE COLLECTION</div><h2>训练手册书架</h2></div><p>七个主题 · 从入门到细节</p></div><div class="shelf">${manuals.map((m,i)=>`<a class="manual-card" href="#manual/${m.id}"><div class="cover" style="--cover:${m.color}"><span class="serial">VOL. 0${i+1}　/　训练知识库</span><h3>${m.title.length>5?m.title.slice(0,4)+'<br>'+m.title.slice(4):m.title}</h3><div class="english">${m.en}</div><span class="glyph" aria-hidden="true">${m.glyph}</span></div><div class="card-body"><p>${m.desc}</p><div class="card-meta"><span>${m.sections.length} 个章节</span><span>开始阅读 →</span></div></div></a>`).join('')}</div></section><section class="start-strip"><div><div class="eyebrow">LESS RUSH. MORE PRACTICE.</div><h2>今天，从一组认真开始。</h2><p>选择推、拉或腿，先热身，再按自己的节奏完成。</p></div><a class="primary" href="#workout">进入今日训练 →</a></section></div>`}
function manual(id){const m=manuals.find(x=>x.id===id);if(!m)return notFound();return header(m.title,m.desc,m.en)+`<div class="reader"><aside class="toc"><strong>本册目录</strong>${m.sections.map(([t],i)=>`<a href="#manual/${id}/s${i}">${String(i+1).padStart(2,'0')}　${t}</a>`).join('')}<a href="#sources/${m.source}">查看对应原文 ↗</a></aside><article><div class="note">整理版 · 动作细节含通用补充。<a href="#videos">原版视频</a>与<a href="#sources">完整技能原文</a>可随时对照。</div>${m.id==='split'?'<div class="chapter-links">'+originalButton('plan','训练计划')+originalButton('terms','名词释义')+'</div>':''}${m.id==='warmup'?'<div class="chapter-links">'+originalButton('warmup','背部热身专项')+originalButton('rowWarmup','上肢热身与划船')+'</div>':''}${m.sections.map(([t,body],i)=>`<section id="s${i}"><h2>${t}</h2>${body}</section>`).join('')}${sourceVideos[m.source]?`<section><h2>相关原视频</h2><p class="subtle">链接来自技能记录与本次原视频来源核对；完整视频不代表已逐句核验。</p>${sourceVideos[m.source].map(([t,b])=>`<p><a class="video" target="_blank" rel="noopener noreferrer" href="https://www.bilibili.com/video/${b}/">${t} ↗</a></p>`).join('')}</section>`:''}<div class="actions"><a class="text-link" href="#library">← 返回书架</a><a class="text-link" href="#sources/${m.source}">核对完整原文 →</a></div></article></div>`}
function notFound(){return header('没有找到这本手册','请回到书架选择想阅读的内容。')+'<div class="wrap"><a class="primary" href="#library">返回书架</a></div>'}
function todayKey(){const d=new Date();return `tcf-checks-${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`}
function sourcesPage(){return header('技能原文与整理说明','完整收录 1 份技能入口与 6 份参考资料。原文保留原样，整理版单独呈现。','SOURCE COLLECTION')+`<div class="wrap"><div class="note source-note">原文是本地技能的学习笔记，不等同于已核验的视频逐字稿。部分说法、数字和个人资料待核实，不作为个体化训练或饮食处方。</div><div class="source-note"><h2>保留完整内容，也说明适用边界</h2><ul><li>完整性：7 份 Markdown 均可展开阅读或下载，未删改原文。</li><li>整理版：纠正训练频率矛盾，避免把“膝盖不能过脚尖”等绝对化提示当成通用规则。</li><li>当前方案：按训练日组织动作与独立组次，不按训练水平分档。</li><li>原版教学：新增三分化计划、胸背腿跟练，以及热身专项；已核对的片段单独标注，完整视频不宣称已逐句核验。</li></ul></div><section class="source-note"><h2>回到原始视频</h2><p>今日训练新增原版跟练入口。单手钢线下拉采用原片名称；腿日第三项采用高脚杯深蹲，并链接对应跟练片段。动作动画仍单独注明器械或替代版本。</p><p>组次和强化安排涉及不同资料版本时，保留明确说明，不能把未核实的讲法写成教练指令。热身参考动作也不等同于完整复现原片。</p><a class="text-link" href="#videos">浏览原版视频目录 →</a></section><section class="source-note media-attribution"><h2>动作动画来源</h2><p>动作与热身示例来自 <a class="text-link" href="https://github.com/DuarteSantos8/openGym" target="_blank" rel="noopener noreferrer">openGym 动作目录 ↗</a>，图片与动画版权归 © Aliaksandr Makatserchyk / Gym visual。动画用于展示动作路线，不是谭成义本人的跟练视频。</p><p>素材按站点所有者确认的独立授权使用，以原始 180 px 版本呈现；辅助版、器械版和替代动作均在示例旁注明。访客如需另行使用素材，请向 Gym visual 获取授权。</p><a class="text-link" href="media/opengym/NOTICE.txt" target="_blank" rel="noopener">查看素材署名与来源说明 ↗</a></section><div class="source-list">${sources.length?sources.map(s=>`<details id="source-${s.file}"><summary>${esc(s.title)}<span>${esc(s.file)}</span></summary><pre>${esc(s.text)}</pre><a href="originals/${encodeURIComponent(s.file)}" download>下载完整 Markdown ↓</a><a target="_blank" href="originals/${encodeURIComponent(s.file)}" rel="noopener">打开原文 ↗</a></details>`).join(''):'<p id="loading-source">正在载入原文…</p>'}</div></div>`}
function fillContent(){document.querySelectorAll('[data-exercises]').forEach(el=>{const v=el.dataset.exercises;el.innerHTML=exercises.filter(e=>v==='all'||e.day===v).map(exerciseDetails).join('')});document.querySelectorAll('[data-exercise]').forEach(el=>{const e=exercises.find(x=>x.id===el.dataset.exercise);el.innerHTML=e?exerciseDetails(e):''});document.querySelectorAll('[data-warmups]').forEach(el=>el.innerHTML=Object.entries({push:'推日',pull:'拉日',legs:'腿日'}).map(([d,t])=>`<details><summary>${t}热身</summary><div class="detail-body">${warmupHtml(d)}</div></details>`).join(''))}
function timerText(){if($('#timer'))$('#timer').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0')}
function stopTimer(){clearInterval(interval);interval=null;deadline=0}
function render(scroll=true){stopTimer();const route=location.hash.slice(1)||'home',parts=route.split('/');document.body.classList.toggle('training-page',parts[0]==='workout');$('#main').innerHTML=parts[0]==='manual'?manual(parts[1]):parts[0]==='workout'?workout():parts[0]==='sources'?sourcesPage():parts[0]==='videos'?videoHub():home();fillContent();bindMedia();if(parts[0]==='workout')bindWorkout();document.title=(parts[0]==='manual'?(manuals.find(m=>m.id===parts[1])?.title||'训练手册'):parts[0]==='workout'?'今日训练':parts[0]==='sources'?'技能原文':parts[0]==='videos'?'原版视频':'谭师训练手册')+' · Tanchengyi Fitness';if(scroll){window.scrollTo(0,0);requestAnimationFrame(()=>{if(route==='library')$('#library')?.scrollIntoView();if(parts[0]==='manual'&&parts[2]){const el=document.getElementById(parts[2]);if(el){if(el.tagName==='DETAILS')el.open=true;el.scrollIntoView()}}if(parts[0]==='sources'&&parts[1]){const el=document.getElementById('source-'+parts[1]);if(el){el.open=true;el.scrollIntoView()}}})}}
function search(){const q=$('#search').value.trim().toLowerCase();if(!q){$('#results').innerHTML='<p class="empty">搜索动作、肌群、热身或恢复主题。</p>';return}const hits=[];exercises.forEach(e=>{if(Object.values(e).join(' ').toLowerCase().includes(q))hits.push({title:e.name,desc:e.muscles+' · 动作细节',url:'#manual/split/'+e.id})});manuals.forEach(m=>m.sections.forEach(([t,b],i)=>{if((m.title+t+b.replace(/<[^>]+>/g,'')).toLowerCase().includes(q))hits.push({title:t,desc:m.title,url:`#manual/${m.id}/s${i}`})}));sources.forEach(s=>{if(s.text.toLowerCase().includes(q))hits.push({title:s.title,desc:'技能原文 · '+s.file,url:'#sources/'+s.file})});$('#results').innerHTML=hits.length?hits.map(h=>`<a href="${h.url}">${esc(h.title)}<small>${esc(h.desc)}</small></a>`).join(''):'<p class="empty">没有找到相关内容，试试其他关键词。</p>';$('#results').querySelectorAll('a').forEach(a=>a.onclick=()=>$('#search-dialog').close())}
$('#search-open').onclick=()=>{$('#search-dialog').showModal();search();$('#search').focus()};$('.close').onclick=()=>$('#search-dialog').close();$('#search').oninput=search;document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search-open').click()}});window.addEventListener('hashchange',()=>render());initTemplates();mountOriginalPlayer();render();fetch('sources.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{sources=d;if(location.hash.startsWith('#sources'))render();if($('#search-dialog').open)search()}).catch(()=>{if($('#loading-source'))$('#loading-source').innerHTML='原文暂时未能载入，请刷新重试。';toast('原文载入失败，请刷新重试。')});
